        //
        // Ingress:
        //      aMagmaLaneD (-->), aMagmaLaneB (-->), aSpiritLaneA (<-?->)
        //
        // Cross:
        //      aMagmaLaneC (<--), aMagmaLaneA (<--), aSpiritLaneB (<-?->)
        //
