            //
            aOrbiterC = ((aOrbiterC + aOrbiterF) + 0xB0961012E36BA02EULL) + aOUSaltA[((aIndex + 90U)) & S_SALT1];
            aOrbiterI = (aOrbiterI ^ aOrbiterC) ^ 0xB56949EE50652607ULL;
