            aOrbiterK = ((aOrbiterK ^ aOrbiterH) ^ 0xA47B8C87A48ECF7AULL) ^ aOUSaltB[((aIndex + 51U)) & S_SALT1];
            aOrbiterK = RotL64((aOrbiterK * 0x17484ECA4A720B41ULL), 27U);
