            //
            aWandererJ = aWandererJ + (((RotL64(aPrevious, 11U) + RotL64(aOrbiterK, 29U)) + aOrbiterG) + aWUSaltF[((aIndex + 93U)) & S_SALT1]);
            aWandererC = aWandererC ^ ((RotL64(aCross, 34U) + RotL64(aOrbiterC, 39U)) + aOrbiterK);
