            aIngress ^= (RotL64(aKeyRowReadB[((aIndex + 29724U)) & W_KEY1], 37U) ^ RotL64(aPlasmaLaneB[((S_BLOCK1 - aIndex + 25766U)) & S_BLOCK1], 5U));
            aIngress = TwistMix64::DiffuseC((aIngress ^ aKeyRotateADomainWordIngress));
