            aScatter = (RotL64(aIngress, 27U) ^ RotL64(aCarry, 58U)) ^ (RotL64(aCross, 13U) + RotL64(aPrevious, 39U));
            aScatter = TwistMix64::DiffuseA((aScatter ^ aKeyRotateADomainWordScatter));
            //
            aOrbiterG = ((aWandererJ + RotL64(aCross, 41U)) + 0x906151DB3B1D0F48ULL) + aOASaltF[((aIndex + 194U)) & S_SALT1];
            aOrbiterJ = (((aWandererA + RotL64(aPrevious, 27U)) + RotL64(aCarry, 3U)) + 0x8E54214EB9C39E2AULL) + aOASaltC[(((511U - aIndex) + 248U)) & S_SALT1];
            aOrbiterH = (aWandererK + RotL64(aScatter, 58U)) + 0x55D555F0B60A67F1ULL;
            aOrbiterE = ((aWandererI + RotL64(aIngress, 47U)) + 0xA3427E20A599A1CCULL) + aOASaltD[((aIndex + 345U)) & S_SALT1];
            aOrbiterB = ((aWandererH + RotL64(aScatter, 3U)) + RotL64(aCarry, 35U)) + 0xDB47BB2ABD2D78AAULL;
            aOrbiterK = ((aWandererD + RotL64(aIngress, 35U)) + 0xC0E9FD173376085BULL) + aOASaltG[((aIndex + 6U)) & S_SALT1];
            aOrbiterI = (((aWandererB + RotL64(aCross, 19U)) + RotL64(aCarry, 19U)) + 0x0EE94AAFD620B3ACULL) + aOASaltH[(((511U - aIndex) + 349U)) & S_SALT1];
            //
            aOrbiterG = ((aOrbiterG + aOrbiterJ) + 0xC8E95363697CA836ULL) + aOUSaltG[(((511U - aIndex) + 381U)) & S_SALT1];
            aOrbiterH = ((aOrbiterH ^ aOrbiterG) ^ 0x9ABD58747707EA7CULL) ^ aOUSaltB[((aIndex + 327U)) & S_SALT1];
            aOrbiterH = RotL64((aOrbiterH * 0x0C1E84A7EFAD74BBULL), 11U);
            //
            aOrbiterE = (aOrbiterE + aOrbiterB) + 0x81AC19644CDFD676ULL;
