            aOrbiterI = (aOrbiterI + aOrbiterG) + 0x8BF5EB10ADC3E704ULL;
            aOrbiterJ = (aOrbiterJ ^ aOrbiterI) ^ 0x2A71428EAA1D36C5ULL;
            aOrbiterJ = RotL64((aOrbiterJ * 0xCE3394156183E9FBULL), 29U);
            //
            aOrbiterK = ((aOrbiterK + aOrbiterI) + 0x285D04DD43ABA95EULL) + aOUSaltC[((aIndex + 307U)) & S_SALT1];
            aOrbiterG = ((aOrbiterG ^ aOrbiterK) ^ 0x7ED21955C548ECBCULL) ^ aOUSaltH[((aIndex + 158U)) & S_SALT1];
            aOrbiterG = RotL64((aOrbiterG * 0x35046F99DB7E4F5DULL), 47U);
            //
            aOrbiterB = (aOrbiterB + aOrbiterK) + 0x1F1C77B64673128FULL;
