            //
            aOrbiterJ = (aOrbiterJ + aOrbiterH) + 0xBD983344FE9424B4ULL;
            aOrbiterE = (aOrbiterE ^ aOrbiterJ) ^ 0xA348B9EEF8950164ULL;
            aOrbiterE = RotL64((aOrbiterE * 0x706ECD26EA42885BULL), 5U);
            //
            aOrbiterH = (aOrbiterH + aOrbiterE) + 0x6B534ECEC314DE04ULL;
            aOrbiterB = (aOrbiterB ^ aOrbiterH) ^ 0xB1AA610F18F6A714ULL;
