            //
            aWandererJ = aWandererJ ^ (((RotL64(aPrevious, 29U) + RotL64(aOrbiterK, 35U)) + aOrbiterE) + aWUSaltB[(((511U - aIndex) + 251U)) & S_SALT1]);
            aWandererD = aWandererD + (((RotL64(aCross, 3U) + aOrbiterG) + RotL64(aOrbiterH, 23U)) + aWUSaltC[((aIndex + 265U)) & S_SALT1]);
            aWandererI = aWandererI ^ (((RotL64(aIngress, 11U) + aOrbiterI) + RotL64(aOrbiterG, 47U)) + aWUSaltG[(((511U - aIndex) + 77U)) & S_SALT1]);
            aWandererH = aWandererH + (((RotL64(aScatter, 46U) + RotL64(aOrbiterI, 11U)) + aOrbiterJ) + RotL64(aCarry, 11U));
            aWandererK = aWandererK ^ (((RotL64(aPrevious, 35U) + RotL64(aOrbiterB, 29U)) + aOrbiterH) + aWUSaltH[((aIndex + 421U)) & S_SALT1]);
