            aOrbiterI = ((aWandererF + RotL64(aIngress, 10U)) + RotL64(aCarry, 51U)) + 0x50620DD9B3825EE2ULL;
            aOrbiterF = ((aWandererK + RotL64(aScatter, 39U)) + 0x4837E9389EBDF115ULL) + aOASaltD[((aIndex + 82U)) & S_SALT1];
            aOrbiterD = (aWandererE + RotL64(aCross, 53U)) + 0x62066068A9DE5904ULL;
            aOrbiterH = ((aWandererJ + RotL64(aPrevious, 21U)) + 0xF012464CF3B5739BULL) + aOASaltE[(((511U - aIndex) + 162U)) & S_SALT1];
            //
            aOrbiterG = ((aOrbiterG + aOrbiterC) + 0xD0488BD60AF052A8ULL) + aOUSaltG[(((511U - aIndex) + 75U)) & S_SALT1];
            aOrbiterE = (aOrbiterE ^ aOrbiterG) ^ 0xF4792529BD6DB87EULL;
            aOrbiterE = RotL64((aOrbiterE * 0x58BAA9AECE81AB35ULL), 47U);
            //
            aOrbiterA = (aOrbiterA + aOrbiterB) + 0xC898314E5A7E4732ULL;
            aOrbiterG = (aOrbiterG ^ aOrbiterA) ^ 0xC7D10B799D4633B4ULL;
            aOrbiterG = RotL64((aOrbiterG * 0x244C4AA50EB5828FULL), 19U);
            //
            aOrbiterI = ((aOrbiterI + aOrbiterA) + 0x0C12B35316C234EFULL) + aOUSaltB[((aIndex + 460U)) & S_SALT1];
            aOrbiterF = (aOrbiterF ^ aOrbiterI) ^ 0xDDB726611CEB63B2ULL;
            aOrbiterF = RotL64((aOrbiterF * 0xB8C4CE37A39AC695ULL), 23U);
            //
            aOrbiterE = ((aOrbiterE + aOrbiterD) + 0xFD69C4E2BB7765C2ULL) + aOUSaltD[(((511U - aIndex) + 419U)) & S_SALT1];
            aOrbiterI = (aOrbiterI ^ aOrbiterE) ^ 0xBEBB9EE82526CE05ULL;
            aOrbiterI = RotL64((aOrbiterI * 0xC962CD83AA6CDB23ULL), 5U);
