            aOrbiterH = (aOrbiterH + aOrbiterE) + 0xCEDC07E5FA269EA3ULL;
            aOrbiterB = (aOrbiterB ^ aOrbiterH) ^ 0x213565642C9CC20CULL;
            aOrbiterB = RotL64((aOrbiterB * 0x23850B7EE944E903ULL), 51U);
            //
            aOrbiterD = (aOrbiterD + aOrbiterH) + 0x69F23BAC43CA33E9ULL;
            aOrbiterA = (aOrbiterA ^ aOrbiterD) ^ 0x79A24BB1F4624C7CULL;
            aOrbiterA = RotL64((aOrbiterA * 0x393D9DA848106785ULL), 13U);
            //
            aOrbiterF = (aOrbiterF + aOrbiterG) + 0x22B0C7C62674E22DULL;
            aOrbiterH = ((aOrbiterH ^ aOrbiterF) ^ 0x8DDABFBC0A48CB4BULL) ^ aOUSaltF[((aIndex + 375U)) & S_SALT1];
            aOrbiterH = RotL64((aOrbiterH * 0xA563D4808CDF62C5ULL), 29U);
